test_that("oracle aligns permutations and reports error", {x<-bench_fixture();o<-check_oracle_genetic_values(x);expect_true(o$ok);expect_equal(o$max_abs_error,0);expect_true(check_oracle_genetic_values(genotypes=x$data$genotypes[,3:1],effects=x$truth$effects,genetic_values=x$truth$genetic_values)$ok);expect_true(check_oracle_genetic_values(genotypes=x$data$genotypes[4:1,],effects=x$truth$effects[,2:1],genetic_values=x$truth$genetic_values[4:1,2:1])$ok);bad<-x$data$genotypes*2;expect_error(check_oracle_genetic_values(genotypes=bad,effects=x$truth$effects,genetic_values=x$truth$genetic_values),"failed");expect_error(check_oracle_genetic_values(genotypes=x$data$genotypes[,-1],effects=x$truth$effects,genetic_values=x$truth$genetic_values),"Missing");b<-x$truth$effects;colnames(b)[1]<-"bad";expect_error(check_oracle_genetic_values(genotypes=x$data$genotypes,effects=b,genetic_values=x$truth$genetic_values),"Missing")})
